// Validate approval-required event payload
const payload = $json.body || $json;

// Payload size limit: max 50KB
const rawString = JSON.stringify(payload);
if (rawString.length > 51200) {
  return [{
    json: {
      is_valid: false,
      error: 'Payload size limit exceeded (maximum 50KB allowed)'
    }
  }];
}

const approval_id = (payload.approval_id || '').trim();
const run_id = (payload.run_id || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!approval_id || !uuidRegex.test(approval_id)) {
  return [{
    json: {
      is_valid: false,
      error: 'Invalid or missing approval_id (must be a valid UUID)'
    }
  }];
}

if (!run_id || !uuidRegex.test(run_id)) {
  return [{
    json: {
      is_valid: false,
      error: 'Invalid or missing run_id (must be a valid UUID)'
    }
  }];
}

const action = payload.action || 'STEP_EXECUTION';
const payload_hash = payload.payload_hash || null;
const proposed_action = payload.proposed_action || {};
const expires_at = payload.expires_at || null;
const correlation_id = payload.correlation_id || ('corr-' + Math.random().toString(36).substring(2, 15));
const idempotency_key = payload.idempotency_key || ('approval:' + approval_id + ':' + (payload_hash || 'v1'));

return [{
  json: {
    is_valid: true,
    approval_id,
    run_id,
    step_id: payload.step_id || null,
    action,
    payload_hash,
    proposed_action,
    expires_at,
    correlation_id,
    idempotency_key,
    requested_at: payload.requested_at || new Date().toISOString()
  }
}];

// Generate Action Links and human notification payload
const val = $('Validate Approval Event').first().json;
const apiBase = $env.AGENTOPS_API_URL || 'http://127.0.0.1:8000';

const approveUrl = `${apiBase}/api/v1/approvals/${val.approval_id}/approve`;
const rejectUrl = `${apiBase}/api/v1/approvals/${val.approval_id}/reject`;

const formattedAlert = `⚠️ **Human Approval Required (Checkpoint Gate)**\n\n` +
  `**Run ID:** \`${val.run_id}\`\n` +
  `**Approval ID:** \`${val.approval_id}\`\n` +
  `**Action Type:** \`${val.action}\`\n` +
  `**Payload Hash:** \`${val.payload_hash || 'none'}\`\n` +
  `**Expires At:** ${val.expires_at || 'No expiration set'}\n\n` +
  `**Proposed Action:**\n\`\`\`json\n${JSON.stringify(val.proposed_action, null, 2)}\n\`\`\`\n\n` +
  `**To Approve:**\nPOST ${approveUrl}\n\n` +
  `**To Reject:**\nPOST ${rejectUrl}\n\n` +
  `*Dispatched via AgentOps n8n Approval Gate Pipeline*`;

return [{
  json: {
    notification_type: 'APPROVAL_REQUESTED',
    approval_id: val.approval_id,
    run_id: val.run_id,
    step_id: val.step_id,
    action: val.action,
    payload_hash: val.payload_hash,
    expires_at: val.expires_at,
    approve_url: approveUrl,
    reject_url: rejectUrl,
    formatted_alert: formattedAlert,
    correlation_id: val.correlation_id,
    idempotency_key: val.idempotency_key,
    status: 'NOTIFIED'
  }
}];
